with base as ((select db_create_time, 'last' as knd\n               from blaze7.client_order co\n               WHERE co.record_type = ANY (ARRAY ['0'::bpchar, '2'::bpchar])\n               order by db_create_time desc\n               limit 1)\n              union all\n              select db_create_time, 'chosen' as knd\n              from blaze7.client_order co\n              WHERE co.record_type = ANY (ARRAY ['0'::bpchar, '2'::bpchar])\n                and co.order_id = 777099916911575040\n                and co.chain_id = 0)\n--select first_value(db_create_time) over () - last_value(db_create_time) over ()\nselect round(extract(epoch from\n                     (first_value(base.db_create_time) over () - last_value(base.db_create_time) over ())::interval) /\n             60, 0)\nfrom base\nlimit 1